CREATE TABLE `api_rate_limit_rules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '限流规则ID',
  `name` varchar(100) NOT NULL COMMENT '规则名称',
  `scope_type` bigint NOT NULL COMMENT '作用范围 1全局 2指定接口',
  `http_method` varchar(10) NOT NULL DEFAULT '*' COMMENT 'HTTP方法',
  `route_path` varchar(255) NOT NULL DEFAULT '*' COMMENT 'Gin路由模板',
  `dimension` bigint NOT NULL COMMENT '限流维度 1 IP 2 UID',
  `rate_count` bigint NOT NULL COMMENT '每个周期补充的令牌数',
  `interval_seconds` bigint NOT NULL COMMENT '令牌补充周期秒数',
  `burst` bigint NOT NULL COMMENT '令牌桶容量和瞬时放行上限',
  `status` bigint NOT NULL DEFAULT '1' COMMENT '状态 0禁用 1启用',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '备注',
  `created_by` bigint unsigned NOT NULL DEFAULT '0' COMMENT '创建管理员ID',
  `updated_by` bigint unsigned NOT NULL DEFAULT '0' COMMENT '最后修改管理员ID',
  `created_at` datetime(3) NOT NULL COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_scope_route_dimension` (`scope_type`,`http_method`,`route_path`,`dimension`),
  KEY `idx_api_rate_limit_rules_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
